def attach_legacy_finance_data(apps, schema_editor):
    Country = apps.get_model("finance", "Country")
    Currency = apps.get_model("finance", "Currency")
    Organization = apps.get_model("finance", "Organization")
    FiscalCalendar = apps.get_model("finance", "FiscalCalendar")
    FiscalPeriod = apps.get_model("finance", "FiscalPeriod")
