    AccountMapping = apps.get_model("finance", "AccountMapping")
    Branch = apps.get_model("finance", "Branch")
    Department = apps.get_model("finance", "Department")
    Expense = apps.get_model("finance", "Expense")

    usd, _ = Currency.objects.get_or_create(
        code="USD",
        defaults={"name": "US Dollar", "symbol": "$", "decimal_places": 2},
    )
    jod, _ = Currency.objects.get_or_create(
        code="JOD",
        defaults={"name": "Jordanian Dinar", "symbol": "JD", "decimal_places": 3},
    )
    jordan, _ = Country.objects.get_or_create(
        iso_code="JO",
        defaults={
            "name": "Jordan",
            "default_currency_id": jod.id,
            "timezone": "Asia/Amman",
        },
    )

    organization, _ = Organization.objects.get_or_create(
        code="DEMO",
        defaults={
            "legal_name": "Demo Finance Organization",
            "display_name": "Demo Finance",
            "default_reporting_currency_id": usd.id,
            "timezone": "Asia/Amman",
        },
    )
    FiscalCalendar.objects.get_or_create(
        organization_id=organization.id,
        code="CAL-2026",
        defaults={"name": "Calendar 2026", "timezone": "Asia/Amman"},
    )
    calendar = FiscalCalendar.objects.get(organization_id=organization.id, code="CAL-2026")
    Organization.objects.filter(id=organization.id).update(
        default_reporting_currency_id=usd.id,
        default_fiscal_calendar_id=calendar.id,
    )
    FiscalPeriod.objects.get_or_create(
        calendar_id=calendar.id,
        code="2026",
        defaults={
            "name": "Fiscal Year 2026",
            "period_type": "year",
            "start_date": date(2026, 1, 1),
            "end_date": date(2026, 12, 31),
            "status": "open",
        },
    )
    entity, _ = LegalEntity.objects.get_or_create(
        organization_id=organization.id,
        code="DEMO-JO",
        defaults={
            "legal_name": "Demo Jordan Entity",
            "short_name": "Demo Jordan",
            "country_id": jordan.id,
            "functional_currency_id": usd.id,
            "reporting_currency_id": usd.id,
            "fiscal_calendar_id": calendar.id,
            "valid_from": date(2026, 1, 1),
            "consolidation_method": "full",
            "status": "active",
        },
    )
    group_account, _ = GroupAccount.objects.get_or_create(
        organization_id=organization.id,
        code="600000",
        defaults={
            "name": "Operating Expenses",
            "account_type": "operating_expense",
            "normal_balance": "debit",
            "level": 1,
            "is_posting_allowed": True,
            "valid_from": date(2026, 1, 1),
        },
    )
    entity_account, _ = EntityAccount.objects.get_or_create(
        legal_entity_id=entity.id,
        code="600000",
        defaults={
            "name": "Operating Expenses",
            "account_type": "operating_expense",
            "normal_balance": "debit",
            "is_posting_allowed": True,
        },
    )
    mapping_version, _ = MappingVersion.objects.get_or_create(
        organization_id=organization.id,
        code="MAP-2026-01",
        defaults={
            "name": "Initial demo account mapping",
            "valid_from": date(2026, 1, 1),
            "status": "approved",
        },
    )
    AccountMapping.objects.get_or_create(
        mapping_version_id=mapping_version.id,
        entity_account_id=entity_account.id,
        group_account_id=group_account.id,
        defaults={
            "mapping_type": "one_to_one",
            "review_status": "approved",
        },
    )

    Branch.objects.all().update(legal_entity_id=entity.id, country_id=jordan.id)
    Department.objects.all().update(legal_entity_id=entity.id, is_active=True)
    for expense in Expense.objects.select_related("department__branch").all():
        branch_id = expense.department.branch_id
        source_record_id = str(expense.id)
        hash_input = "|".join(
            [
                "django",
                "finance_expense",
                source_record_id,
                str(expense.amount),
                expense.currency,
                expense.expense_date.isoformat(),
                expense.description,
            ]
        )
        expense.branch_id = branch_id
        expense.legal_entity_id = entity.id
        expense.entity_account_id = entity_account.id
        expense.group_account_id = group_account.id
        expense.currency_master_id = usd.id
        expense.source_record_id = source_record_id
        expense.source_created_at = expense.created_at
        expense.source_updated_at = expense.updated_at
        expense.record_hash = hashlib.sha256(hash_input.encode("utf-8")).hexdigest()
        expense.save(
            update_fields=[
                "branch",
                "legal_entity",
                "entity_account",
                "group_account",
                "currency_master",
                "source_record_id",
                "source_created_at",
                "source_updated_at",
                "record_hash",
                "updated_at",
            ]
        )


